{"constats":[{"id":"C1","fichier":"src/wavedevsecops/web/blockers.py","ligne":75,"severite":"Important","description":"Pour une station non livrée sans milestone, le repli utilise chain.map.soon_text plutôt que « Bientôt ». Ce texte appartient à la carte et peut être différent : l'encart affiche alors ce texte à la place du repli explicitement imposé par la story.","test_pytest":"import importlib
from types import SimpleNamespace


def test_station_sans_jalon_affiche_bientot(monkeypatch):
    try:
        module = importlib.import_module('usine.web.blockers')
    except ModuleNotFoundError as error:
        if error.name not in {'usine', 'usine.web', 'usine.web.blockers'}:
            raise
        module = importlib.import_module('wavedevsecops.web.blockers')

    station = SimpleNamespace(
        number=2, name='PR et CI', delivered=False, milestone='',
        barriers=[SimpleNamespace(id='protection', label='Protection de main')],
    )
    chain = SimpleNamespace(
        stations=[station],
        map=SimpleNamespace(soon_text='Prochainement sur la carte'),
    )
    scenario = SimpleNamespace(
        key='push-pull.B',
        blocked_by=[SimpleNamespace(
            barrier_id='protection', station=2,
            scenario_id='push-direct-main', reason_text='main est protégée.',
        )],
    )
    monkeypatch.setattr(module, 'load_chain_texts', lambda settings: chain)
    monkeypatch.setattr(module, 'catalogue_scenario_titles', lambda settings: {})

    body = module.blockers_body(scenario, SimpleNamespace())

    assert body['items'][0]['soon_text'] == 'Bientôt'
    assert body['items'][0]['scenario'] is None
